contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount is the amount we send to c.deposit; must be <= this contract balance
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // Record observable balances before any interaction
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform deposit to give this contract credit in C
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Observables after deposit
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observables after withdraw attempt
        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;

        // If withdrawAll returned (did not revert) then the increase in this contract's balance
        // equals the decrease in C's balance, and that decrease equals the amount transferred out
        // which must be at most the deposited amount — we express equality between observed flows.
        assert(
            reverted || (
                // money conservation between C and this contract for the withdraw operation
                (finalThis - afterDepositThis) == (afterDepositC - finalC)
            )
        );
    }

    // allow receiving Ether from C during withdrawAll
    receive() external payable {}
}

