// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;
        assertTrue(reverted || (
                // money conservation between C and this contract for the withdraw operation
                (finalThis - afterDepositThis) == (afterDepositC - finalC)
            ));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
